package com.procuremind.platform.agentintegration;

import com.procuremind.platform.common.ApiResponse;
import com.procuremind.platform.common.BusinessException;
import com.procuremind.platform.purchaseorder.PurchaseOrderService;
import com.procuremind.platform.system.SecurityUtils;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;

/** 旧 MCP 工具协议的内部适配层。仅内部令牌认证可以访问，不经 Nginx 对外暴露。 */
@RestController
@RequestMapping("/api")
public class LegacyErpController {
    private final JdbcTemplate jdbc; private final PurchaseOrderService orders;
    public LegacyErpController(JdbcTemplate jdbc,PurchaseOrderService orders){this.jdbc=jdbc;this.orders=orders;}

    @GetMapping("/suppliers/search") ApiResponse<List<Map<String,Object>>> supplierSearch(@RequestParam String name){return ApiResponse.ok(supplierRows("%"+name+"%",100,0));}
    @GetMapping("/suppliers/page") ApiResponse<Map<String,Object>> supplierPage(@RequestParam(defaultValue="1")int current,@RequestParam(defaultValue="10")int size,@RequestParam(required=false)String name,@RequestParam(required=false)Integer status,@RequestParam(required=false)String creditRating){String keyword="%"+(name==null?"":name)+"%";List<Map<String,Object>> records=jdbc.queryForList("select cast(id as char) id,code supplierCode,name,contact_name contactPerson,contact_phone phone,email,address,level creditRating,(status='QUALIFIED') status,score from sp_supplier where deleted=0 and name like ? and (? is null or level=?) and (? is null or (status='QUALIFIED')=?) order by id limit ? offset ?",keyword,creditRating,creditRating,status,status,size,(current-1)*size);Long total=jdbc.queryForObject("select count(*) from sp_supplier where deleted=0 and name like ? and (? is null or level=?) and (? is null or (status='QUALIFIED')=?)",Long.class,keyword,creditRating,creditRating,status,status);return ApiResponse.ok(page(records,total,current,size));}
    @GetMapping("/suppliers/get/{id}") ApiResponse<Map<String,Object>> supplierGet(@PathVariable Long id){return ApiResponse.ok(jdbc.queryForMap("select cast(id as char) id,code supplierCode,name,unified_credit_code unifiedCreditCode,contact_name contactPerson,contact_phone phone,email,address,level creditRating,(status='QUALIFIED') status,score from sp_supplier where id=? and deleted=0",id));}
    @PostMapping("/suppliers/create") @Transactional ApiResponse<Map<String,Object>> supplierCreate(@RequestBody Map<String,Object> r){String code=required(r,"supplierCode"),name=required(r,"name");jdbc.update("insert into sp_supplier(code,name,level,status,contact_name,contact_phone,email,address,created_by,updated_by) values(?,?,?,?,?,?,?,?,?,?)",code,name,text(r,"creditRating","B"),integer(r,"status",1)==1?"QUALIFIED":"SUSPENDED",r.get("contactPerson"),r.get("phone"),r.get("email"),r.get("address"),user(),user());return ApiResponse.ok(Map.of("id",jdbc.queryForObject("select id from sp_supplier where code=?",Long.class,code)));}
    @PatchMapping("/suppliers/update-status/{id}") ApiResponse<Void> supplierStatus(@PathVariable Long id,@RequestParam int status){jdbc.update("update sp_supplier set status=?,updated_by=? where id=?",status==1?"QUALIFIED":"SUSPENDED",user(),id);return ApiResponse.ok(null);}

    @GetMapping("/parts/get/{id}") ApiResponse<Map<String,Object>> partGet(@PathVariable Long id){return ApiResponse.ok(jdbc.queryForMap(partSelect()+" where m.id=? and m.deleted=0",id));}
    @GetMapping("/parts/search") ApiResponse<List<Map<String,Object>>> partSearch(@RequestParam String name){return ApiResponse.ok(jdbc.queryForList(partSelect()+" where m.deleted=0 and m.name like ? order by m.id limit 100","%"+name+"%"));}
    @GetMapping("/parts/page") ApiResponse<Map<String,Object>> partPage(@RequestParam(defaultValue="1")int current,@RequestParam(defaultValue="10")int size,@RequestParam(required=false)String name,@RequestParam(required=false)String category,@RequestParam(required=false)Long supplierId){String keyword="%"+(name==null?"":name)+"%",cat="%"+(category==null?"":category)+"%";List<Map<String,Object>> records=jdbc.queryForList(partSelect()+" where m.deleted=0 and m.name like ? and c.name like ? order by m.id limit ? offset ?",keyword,cat,size,(current-1)*size);Long total=jdbc.queryForObject("select count(*) from md_material m join md_material_category c on c.id=m.category_id where m.deleted=0 and m.name like ? and c.name like ?",Long.class,keyword,cat);return ApiResponse.ok(page(records,total,current,size));}
    @GetMapping("/parts/supplier/{supplierId}") ApiResponse<List<Map<String,Object>>> partsBySupplier(@PathVariable Long supplierId){return ApiResponse.ok(jdbc.queryForList(partSelect()+" where m.deleted=0 and exists(select 1 from po_purchase_order_item i join po_purchase_order o on o.id=i.purchase_order_id where i.material_id=m.id and o.supplier_id=?)",supplierId));}
    @PostMapping("/parts/create") @Transactional ApiResponse<Map<String,Object>> partCreate(@RequestBody Map<String,Object> r){String code=required(r,"partCode"),name=required(r,"name");Long category=jdbc.query("select id from md_material_category where name=? and deleted=0 limit 1",rs->{return rs.next()?rs.getLong(1):1L;},r.get("category"));Long unit=jdbc.query("select id from md_unit where name=? or code=? limit 1",rs->{return rs.next()?rs.getLong(1):1L;},r.get("unit"),r.get("unit"));String spec=String.join(" ",List.of(text(r,"model","").trim(),text(r,"specification","").trim())).trim();jdbc.update("insert into md_material(code,name,category_id,unit_id,specification,tracking_mode,min_stock,created_by,updated_by) values(?,?,?,?,?,'QUANTITY',?,?,?)",code,name,category,unit,spec,decimal(r,"stockWarningValue",BigDecimal.ZERO),user(),user());return ApiResponse.ok(Map.of("id",jdbc.queryForObject("select id from md_material where code=?",Long.class,code)));}

    @GetMapping("/orders/page") ApiResponse<Map<String,Object>> orderPage(@RequestParam(defaultValue="1")int current,@RequestParam(defaultValue="10")int size,@RequestParam(required=false)String orderNumber,@RequestParam(required=false)Integer status,@RequestParam(required=false)String startDate,@RequestParam(required=false)String endDate){String keyword="%"+(orderNumber==null?"":orderNumber)+"%";String state=status==null?null:legacyStatus(status);List<Map<String,Object>> records=jdbc.queryForList("select cast(o.id as char) id,o.order_no orderNumber,o.total_amount totalAmount,o.status,o.created_at orderTime,s.name supplierName from po_purchase_order o join sp_supplier s on s.id=o.supplier_id where o.deleted=0 and o.order_no like ? and (? is null or o.status=?) and (? is null or date(o.created_at)>=?) and (? is null or date(o.created_at)<=?) order by o.id desc limit ? offset ?",keyword,state,state,startDate,startDate,endDate,endDate,size,(current-1)*size);Long total=jdbc.queryForObject("select count(*) from po_purchase_order o where o.deleted=0 and o.order_no like ? and (? is null or o.status=?) and (? is null or date(o.created_at)>=?) and (? is null or date(o.created_at)<=?)",Long.class,keyword,state,state,startDate,startDate,endDate,endDate);return ApiResponse.ok(page(records,total,current,size));}
    @GetMapping("/orders/get/{id}") ApiResponse<Map<String,Object>> orderGet(@PathVariable Long id){return ApiResponse.ok(orders.detail(id));}
    @GetMapping("/orders/search-details") ApiResponse<List<Map<String,Object>>> orderDetails(@RequestParam(required=false)String partName,@RequestParam(required=false)String startDate,@RequestParam(required=false)String endDate){return ApiResponse.ok(jdbc.queryForList("select o.order_no orderNumber,m.code partCode,m.name partName,i.quantity,i.unit_price unitPrice,s.name supplierName,o.created_at orderTime from po_purchase_order_item i join po_purchase_order o on o.id=i.purchase_order_id join md_material m on m.id=i.material_id join sp_supplier s on s.id=o.supplier_id where i.deleted=0 and m.name like ? and (? is null or date(o.created_at)>=?) and (? is null or date(o.created_at)<=?) order by o.created_at desc","%"+(partName==null?"":partName)+"%",startDate,startDate,endDate,endDate));}
    @GetMapping("/orders/statistics") ApiResponse<Map<String,Object>> orderStatistics(@RequestParam(required=false)String startDate,@RequestParam(required=false)String endDate){Map<String,Object>d=new LinkedHashMap<>();d.put("orderCount",jdbc.queryForObject("select count(*) from po_purchase_order where deleted=0 and (? is null or date(created_at)>=?) and (? is null or date(created_at)<=?)",Long.class,startDate,startDate,endDate,endDate));d.put("totalAmount",jdbc.queryForObject("select coalesce(sum(total_amount),0) from po_purchase_order where deleted=0 and (? is null or date(created_at)>=?) and (? is null or date(created_at)<=?)",BigDecimal.class,startDate,startDate,endDate,endDate));d.put("statusCounts",jdbc.queryForList("select status,count(*) count from po_purchase_order where deleted=0 group by status"));return ApiResponse.ok(d);}
    @PostMapping("/orders/create") @Transactional ApiResponse<Map<String,Object>> orderCreate(@RequestBody Map<String,Object> r){String no=text(r,"orderNumber","PO"+System.currentTimeMillis());Long supplier=longValue(r,"supplierId",jdbc.queryForObject("select id from sp_supplier where status='QUALIFIED' and deleted=0 order by score desc limit 1",Long.class));List<Map<String,Object>> items=items(r);if(items.isEmpty())throw new BusinessException(HttpStatus.BAD_REQUEST,"订单明细不能为空");BigDecimal total=items.stream().map(i->decimal(i,"quantity",BigDecimal.ZERO).multiply(decimal(i,"unitPrice",BigDecimal.ZERO))).reduce(BigDecimal.ZERO,BigDecimal::add);jdbc.update("insert into po_purchase_order(order_no,supplier_id,purchaser_id,delivery_date,tax_rate,total_amount,terms,created_by,updated_by) values(?,?,?,?,0,?,?,?,?)",no,supplier,user(),LocalDate.now().plusDays(7),total,r.get("remark"),user(),user());Long id=jdbc.queryForObject("select id from po_purchase_order where order_no=?",Long.class,no);for(Map<String,Object> i:items)jdbc.update("insert into po_purchase_order_item(purchase_order_id,material_id,quantity,unit_price,tax_rate,remark,created_by,updated_by) values(?,?,?,?,0,?,?,?)",id,longValue(i,"partId",null),decimal(i,"quantity",BigDecimal.ZERO),decimal(i,"unitPrice",BigDecimal.ZERO),i.get("remark"),user(),user());return ApiResponse.ok(Map.of("id",id,"orderNumber",no,"status","DRAFT"));}
    @PutMapping("/orders/update/{id}") @Transactional ApiResponse<Void> orderUpdate(@PathVariable Long id,@RequestBody Map<String,Object> r){String state=jdbc.queryForObject("select status from po_purchase_order where id=? for update",String.class,id);if(!List.of("DRAFT","REJECTED").contains(state))throw new BusinessException(HttpStatus.CONFLICT,"仅草稿或驳回订单可修改");List<Map<String,Object>> items=items(r);if(!items.isEmpty()){jdbc.update("delete from po_purchase_order_item where purchase_order_id=?",id);BigDecimal total=BigDecimal.ZERO;for(Map<String,Object> i:items){BigDecimal q=decimal(i,"quantity",BigDecimal.ZERO),p=decimal(i,"unitPrice",BigDecimal.ZERO);total=total.add(q.multiply(p));jdbc.update("insert into po_purchase_order_item(purchase_order_id,material_id,quantity,unit_price,tax_rate,remark,created_by,updated_by) values(?,?,?,?,0,?,?,?)",id,longValue(i,"partId",null),q,p,i.get("remark"),user(),user());}jdbc.update("update po_purchase_order set total_amount=?,terms=?,status='DRAFT',updated_by=? where id=?",total,r.get("remark"),user(),id);}return ApiResponse.ok(null);}
    @PatchMapping("/orders/update-status/{id}") ApiResponse<Void> orderStatus(@PathVariable Long id,@RequestParam int status){if(status==1){orders.submit(id);return ApiResponse.ok("订单已提交正式审批流程",null);}if(status==4&&jdbc.update("update po_purchase_order set status='CLOSED',updated_by=? where id=? and status='RECEIVED'",user(),id)==1)return ApiResponse.ok(null);throw new BusinessException(HttpStatus.CONFLICT,"Agent不能绕过审批或收货流程直接修改该状态");}

    @GetMapping("/inventory/warning") ApiResponse<List<Map<String,Object>>> inventoryWarning(){return ApiResponse.ok(inventoryRows(" where b.quantity<m.min_stock",1000,0));}
    @GetMapping("/inventory/page") ApiResponse<Map<String,Object>> inventoryPage(@RequestParam(defaultValue="1")int current,@RequestParam(defaultValue="10")int size,@RequestParam(required=false)String partName,@RequestParam(required=false)String warehouseLocation){String filter=" where m.name like ? and (w.name like ? or w.address like ?)",p="%"+(partName==null?"":partName)+"%",w="%"+(warehouseLocation==null?"":warehouseLocation)+"%";List<Map<String,Object>> rows=jdbc.queryForList(inventorySelect()+filter+" order by b.id limit ? offset ?",p,w,w,size,(current-1)*size);Long total=jdbc.queryForObject("select count(*) from inv_balance b join md_material m on m.id=b.material_id join md_warehouse w on w.id=b.warehouse_id"+filter,Long.class,p,w,w);return ApiResponse.ok(page(rows,total,current,size));}
    @GetMapping("/inventory/check") ApiResponse<Map<String,Object>> inventoryCheck(){return ApiResponse.ok(Map.of("totalSku",jdbc.queryForObject("select count(*) from inv_balance where deleted=0",Long.class),"warningCount",jdbc.queryForObject("select count(*) from inv_balance b join md_material m on m.id=b.material_id where b.deleted=0 and b.quantity<m.min_stock",Long.class),"totalQuantity",jdbc.queryForObject("select coalesce(sum(quantity),0) from inv_balance where deleted=0",BigDecimal.class)));}
    @GetMapping("/inventory/get/{id}") ApiResponse<Map<String,Object>> inventoryGet(@PathVariable Long id){return ApiResponse.ok(jdbc.queryForMap(inventorySelect()+" where b.id=?",id));}
    @PostMapping({"/inventory/inbound","/inventory/outbound"}) ApiResponse<Void> legacyInventoryWrite(){throw new BusinessException(HttpStatus.CONFLICT,"库存变动必须通过已审批订单的正式收货接口，Agent不能直接调整库存");}

    private List<Map<String,Object>> supplierRows(String keyword,int size,int offset){return jdbc.queryForList("select cast(id as char) id,code supplierCode,name,contact_name contactPerson,contact_phone phone,email,address,level creditRating,(status='QUALIFIED') status,score from sp_supplier where deleted=0 and name like ? order by score desc limit ? offset ?",keyword,size,offset);}
    private String partSelect(){return "select cast(m.id as char) id,m.code partCode,m.name,m.specification model,m.specification,u.name unit,m.min_stock stockWarningValue,c.name category,m.tracking_mode trackingMode from md_material m join md_material_category c on c.id=m.category_id join md_unit u on u.id=m.unit_id";}
    private String inventorySelect(){return "select cast(b.id as char) id,b.quantity currentQuantity,m.min_stock safetyStock,w.name warehouseLocation,m.code partCode,m.name partName,m.tracking_mode trackingMode from inv_balance b join md_material m on m.id=b.material_id join md_warehouse w on w.id=b.warehouse_id";}
    private List<Map<String,Object>> inventoryRows(String where,int size,int offset){return jdbc.queryForList(inventorySelect()+where+" order by b.id limit ? offset ?",size,offset);}
    private Map<String,Object> page(List<Map<String,Object>> records,long total,int current,int size){return Map.of("records",records,"total",total,"current",current,"size",size,"pages",(total+size-1)/size);}
    @SuppressWarnings("unchecked") private List<Map<String,Object>> items(Map<String,Object> r){Object v=r.get("orderDetail");return v instanceof List<?> list?list.stream().filter(Map.class::isInstance).map(x->(Map<String,Object>)x).toList():List.of();}
    private long user(){return SecurityUtils.currentUser().id();}
    private String required(Map<String,Object> r,String key){String v=String.valueOf(r.getOrDefault(key,"")).trim();if(v.isEmpty())throw new BusinessException(HttpStatus.BAD_REQUEST,key+"不能为空");return v;}
    private String text(Map<String,Object> r,String key,String fallback){Object v=r.get(key);return v==null?fallback:String.valueOf(v);}
    private int integer(Map<String,Object> r,String key,int fallback){Object v=r.get(key);return v==null?fallback:Integer.parseInt(v.toString());}
    private Long longValue(Map<String,Object> r,String key,Long fallback){Object v=r.get(key);return v==null?fallback:Long.valueOf(v.toString());}
    private BigDecimal decimal(Map<String,Object> r,String key,BigDecimal fallback){Object v=r.get(key);return v==null?fallback:new BigDecimal(v.toString());}
    private String legacyStatus(int value){return switch(value){case 0->"DRAFT";case 1->"APPROVED";case 2->"PARTIALLY_RECEIVED";case 3->"RECEIVED";case 4->"CLOSED";default->null;};}
}
